const fieldNames={care:'Care & support',community:'Community & wellbeing',health:'Allied health',business:'Business'};
function courseContent(category,kind){const fragment=document.createDocumentFragment();window.AIFL_COURSES.filter(c=>c.category===category).forEach(course=>{const article=document.createElement('article');article.className=kind+'-course';const title=document.createElement('h3');title.textContent=course.title;const code=document.createElement('small');code.textContent=course.qualification;const description=document.createElement('p');description.textContent=course.description;const link=document.createElement('a');link.href=course.url;link.className='solid-link';link.textContent='View course details';link.setAttribute('aria-label','View '+course.title+' course');if(window.self!==window.top){link.target='_blank';link.rel='noopener'}article.append(title,code,description,link);fragment.append(article)});return fragment}
const guide=document.querySelector('#guide-courses');if(guide){function showField(field){document.querySelectorAll('[data-interest]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.interest===field)));document.querySelector('#results-title').textContent=fieldNames[field];const count=window.AIFL_COURSES.filter(c=>c.category===field).length;document.querySelector('#guide-count').textContent=count+' '+(count===1?'course':'courses');guide.replaceChildren(courseContent(field,'guide'))}showField('care');document.querySelectorAll('[data-interest]').forEach(button=>button.addEventListener('click',()=>showField(button.dataset.interest)))}
const dialog=document.querySelector('#area-dialog');if(dialog){document.querySelectorAll('[data-area]').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#area-title').textContent=fieldNames[button.dataset.area];document.querySelector('#area-courses').replaceChildren(courseContent(button.dataset.area,'atlas'));dialog.showModal()}));document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}})}
